const roofing_bu_uid = "5085e880-1fbb-48a3-a60e-ecc3116ad653";
const gutter_bu_uid = "608e2381-f927-4441-b1aa-9b1e60f513c4";
const siding_bu_uid = "3d697d6b-b76a-417c-ad88-fe439f2028cb";

const inspection = ["Inspection Report"]
const production_roof = ["Site Preparation","Tear-Off (Removal of Old Roof)","Shingle or Roofing Material Installation","Cleanup & Waste Disposal","Final Inspection","Punchlist"]
const production_gutter = ["Site Preparation","Tear off Downspout & Gutter","Install Gutters","Cleanup & Waste Disposal","Final Inspection","Punchlist"]
const production_siding = ["Site Preparation","Strip old siding","Install Siding","Cleanup & Waste Disposal","Final Inspection","Punchlist"]

return {roofing_bu_uid, gutter_bu_uid, siding_bu_uid, inspection, production_roof, production_gutter, production_siding};

const normalize = (str) => (str ?? "").toString().trim().toLowerCase();
const moment = require("moment");
const job_data = $input.job_data;
const current_status = $input.current_status;
const service_tasks = $input.service_tasks;
const job_uid = job_data.job_uid;
const base_url = $.getVariable('BASE_URL');
const po_uid = $input.po_uid;
const lineItems = $input.job_line_items; // your array of line items
const trades = lineItems.filter(item => item.line_item_type === "GROUP").map(item => item.product_name);
const job_tasks = $input.job_tasks;               // full list of existing job service tasks (GET service_tasks response)
const inspection_tasks = $input.inspection_tasks;  // e.g. ["Inspection Report"]
const production_roof_tasks = $input.production_roof_tasks;     // e.g. ["Site Preparation", "Tear-Off (Removal of Old Roof)", ...]
const production_gutter_tasks = $input.production_gutter_tasks; // e.g. ["Tear off Downspout & Gutter", "Install Gutters", ...]
const production_siding_tasks = $input.production_siding_tasks; // e.g. ["Strip old siding", "Install Siding", ...]

const purchase_orders = po_uid.map((uid) => ({
  purchase_order_uid: uid
}));

// ---- Trade -> its own production task title list ----
// (mirrors the TRADE_TASKS_MAP used in the service-task creation script —
// same per-trade lists, just consumed here to look up existing uids instead
// of building new task payloads.)
const TRADE_TASKS_MAP = {
  Roof: production_roof_tasks,
  Gutters: production_gutter_tasks,
  Siding: production_siding_tasks
};

// ---- Resolve service_task_uid(s) from job_tasks by title ----

// INSPECTION: one uid per title. Any existing appointment link on that task
// is fine to reuse (this mirrors the original hardcoded behavior, which
// pointed at a task that already had an appointment attached).
function getInspectionServiceTaskUid(title) {
  const match = job_tasks.find(
    (t) => normalize(t.service_task_title) === normalize(title)
  );
  if (!match) {
    throw new Error(`No job task found for inspection title "${title}"`);
  }
  return { service_task_uid: match.service_task_uid };
}

// PRODUCTION: since each trade now has its own distinct title list (no title
// appears under more than one trade)... except when it does — a few generic
// closeout titles (Site Preparation, Cleanup & Waste Disposal, Final
// Inspection, Punchlist) show up in more than one trade's list. A separate
// job task instance DOES exist per (trade, title) pair from the creation
// step, but without tracking what's already been picked, every trade would
// independently select the SAME "first unassigned" match for a shared
// title — and whichever appointment gets created last ends up stealing that
// task from the one created earlier. `usedUids` prevents that: once a uid is
// handed out to one trade, it's excluded from every later lookup in this run.
const usedUids = new Set();

function getAvailableUidForTitle(title) {
  const match = job_tasks
    .filter(
      (t) =>
        normalize(t.service_task_title) === normalize(title) &&
        !t.appointment &&
        !usedUids.has(t.service_task_uid)
    )
    .sort((a, b) => (a.sequence_no ?? 0) - (b.sequence_no ?? 0))[0];

  if (!match) {
    throw new Error(`No unassigned job task found for production title "${title}"`);
  }
  usedUids.add(match.service_task_uid);
  return match.service_task_uid;
}

function getServiceTasksForTrade(trade) {
  const tradeTasks = TRADE_TASKS_MAP[trade] || [];
  return tradeTasks.map((title) => ({
    service_task_uid: getAvailableUidForTitle(title)
  }));
}

// ---- Determine which appointments to create ----
let selected_values = [];
if (current_status === "Claim Pending") {
  selected_values = ["Adjuster Visit"];
} else if (current_status === "Ready for Inspection") {
  selected_values = ["Inspection"];
} else if (current_status === "Approved" || current_status === "Insurance Review") {
  if (trades.includes("Roof")) {
    selected_values.push("Production-Roof");
  }
  if (trades.includes("Gutters")) {
    selected_values.push("Production-Gutters");
  }
  if (trades.includes("Siding")) {
    selected_values.push("Production-Siding");
  }
}

const VALUE_TO_TRADE = {
  "Production-Roof": "Roof",
  "Production-Gutters": "Gutters",
  "Production-Siding": "Siding"
};

const appointment_url = `${base_url}/appointments`;

// --- One create payload + association payload per selected value ---
const appointments = selected_values.map((value) => {
  const appointment_title = `${value}`;
  let payload = {};
  let service_task = [];

  if (value === "Inspection" || value === "Adjuster Visit") {
    service_task =
      value === "Inspection"
        ? inspection_tasks.map(getInspectionServiceTaskUid)
        : [];

    payload = {
      appointment: {
        job_uid: job_uid,
        appointment_title: appointment_title,
        purchase_orders: [],
        service_tasks: service_task
      }
    };
  } else {
    const trade = VALUE_TO_TRADE[value];
    service_task = getServiceTasksForTrade(trade);

    let bu_uid = "";
    if (value === "Production-Roof") {
      bu_uid = $input.roofing_bu_uid;
    } else if (value === "Production-Gutters") {
      bu_uid = $input.gutters_bu_uid;
    } else if (value === "Production-Siding") {
      bu_uid = $input.siding_bu_uid;
    }

    payload = {
      appointment: {
        job_uid: job_uid,
        bu_uid: bu_uid,
        appointment_title: appointment_title,
        purchase_orders: purchase_orders,
        service_tasks: service_task
      }
    };
  }

  return {
    service: value,
    appointment_update_payload: {
      url: appointment_url,
      payload
    }
  };
});

return {
  data: {
    appointments,
    job_uid,
    base_url // for assembling the association URL downstream
  }
};

// ---- Inputs ----

const lineItems = $input.job_line_items; // your array of line items
const trades = lineItems.filter(item => item.line_item_type === "GROUP").map(item => item.product_name);
const current_status = $input.current_status;
const roofing_bu = $input.roofing_bu;
const gutter_bu = $input.gutter_bu;
const siding_bu = $input.siding_bu;
const task_master = $input.task_master;         // array of master task records (as shown in your sample data)
const inspection_tasks = $input.inspection_tasks;   // e.g. ["Inspection Report"]
const production_roof_tasks = $input.production_roof_tasks;     // e.g. ["Site Preparation", "Tear-Off (Removal of Old Roof)", ...]
const production_gutter_tasks = $input.production_gutter_tasks; // e.g. ["Tear off Downspout & Gutter", "Install Gutters", ...]
const production_siding_tasks = $input.production_siding_tasks; // e.g. ["Strip old siding", "Install Siding", ...]
const module_uid = $input.job_uid;

// ---- Trade -> BU lookup ----
const TRADE_BU_MAP = {
  Roof: roofing_bu,
  Gutters: gutter_bu,
  Siding: siding_bu
};

// ---- Trade -> its own production task title list ----
const TRADE_TASKS_MAP = {
  Roof: production_roof_tasks,
  Gutters: production_gutter_tasks,
  Siding: production_siding_tasks
};

// ---- Build a title -> master record lookup ----
// NOTE: a few titles repeat in the raw task_master data (e.g. "Install Gutters" x2,
// "Inspection"/"Inspection\t" x3 across different trade sequences). This lookup keeps
// the FIRST match per title. That's safe for the current inspection_tasks/production_tasks
// lists (their titles are each unique in the data), but if you ever add a title that's
// duplicated across trades, you'll need to key by something more specific
// (e.g. service_task_master_uid directly, or scope the lookup per trade).
const taskMasterByTitle = {};
for (const t of task_master) {
  const title = (t.service_task_title || "").trim();
  if (title && !(title in taskMasterByTitle)) {
    taskMasterByTitle[title] = t;
  }
}

// ---- Due date helper ----
// Your sample payload used a fixed due_date. There's nothing in the input to derive
// one from, so this defaults every task to "10 days from now at 04:59:59Z" (matching
// the sample's time format). Replace with real scheduling logic whenever you have it.
function getDueDate() {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 10);
  d.setUTCHours(4, 59, 59, 0);
  return d.toISOString().replace(".000Z", "Z");
}

// ---- Payload builder ----
function buildServiceTask(title, buUids) {
  const master = taskMasterByTitle[title];
  if (!master) {
    throw new Error(`No task master found for title "${title}"`);
  }

  const payload = {
    service_task_title: master.service_task_title.trim(),
    task_type: master.task_type || "TASK",
    due_date: getDueDate(),
    service_task_master_uid: master.service_task_master_uid,
    priority: master.priority || "NONE",
    bu_uids: buUids,
    module: "JOB",
    module_uid: module_uid,
    auto_add_task_assignee: true,
    estimated_duration: master.estimated_duration || { days: 0, hours: 0, minutes: 0 }
  };

  // Only include inspection_form if the master record actually has one
  if (master.inspection_form && master.inspection_form.asset_form_uid) {
    payload.inspection_form = master.inspection_form.asset_form_uid;
  }

  return payload;
}

// ---- Main logic ----
let tasks = [];

if (current_status === "Ready for Inspection") {
  // One task per inspection_tasks title.
  // bu_uids here = the BUs for every trade on this job combined, since an
  // inspection task isn't scoped to a single trade.
  const allBuUids = trades.map(tr => TRADE_BU_MAP[tr]).filter(Boolean);
  tasks = inspection_tasks.map(title => buildServiceTask(title, allBuUids));

} else if (current_status === "Approved" || current_status === "Insurance Review") {
  // One task per title in THAT trade's own task list, scoped to that
  // trade's business unit only (no more cross-multiplying every title
  // against every trade — Roof titles only ever get roofing_bu, etc.).
  for (const trade of trades) {
    const buUid = TRADE_BU_MAP[trade];
    const tradeTasks = TRADE_TASKS_MAP[trade];

    if (!buUid || !tradeTasks) continue; // unrecognized trade name, skip rather than error

    for (const title of tradeTasks) {
      tasks.push(buildServiceTask(title, [buUid]));
    }
  }
}

// Each task payload gets its own "service_tasks" wrapper (one array item per
// wrapper) instead of a single shared array holding every task. This returns
// one output item per task, ready for a downstream node to POST individually.
return tasks.map(task => ({ service_tasks: [task] }));
